assert_eq!(caught(|| x86_64::align_down(1233, 16)), Some(1232u64), "case 31: align_down(1233, 16)");
assert_eq!(caught(|| x86_64::align_down(18446744073709551615, 2)), Some(18446744073709551614u64), "case 32: align_down(18446744073709551615, 2)");
assert_eq!(caught(|| x86_64::align_down(0, 1)), Some(0u64), "case 33: align_down(0, 1)");
assert_eq!(caught(|| x86_64::align_down(123, 0)), None, "case 34: align_down(123, 0)");
assert_eq!(caught(|| x86_64::align_down(123, 3)), None, "case 35: align_down(123, 3)");
assert_eq!(caught(|| VirtAddr::new(140737488355327).align_up(2u64).as_u64()), Some(18446603336221196288u64), "case 36: virtual_align(140737488355327, 2, true)");
assert_eq!(caught(|| VirtAddr::new(18446603336221196288).align_down(281474976710656u64).as_u64()), Some(0u64), "case 37: virtual_align(18446603336221196288, 281474976710656, false)");
assert_eq!(caught(|| VirtAddr::new(18446744073709551615).align_up(2u64).as_u64()), None, "case 38: virtual_align(18446744073709551615, 2, true)");
assert_eq!(caught(|| VirtAddr::new(1233).align_up(2u64).as_u64()), Some(1234u64), "case 39: virtual_align(1233, 2, true)");
assert_eq!(caught(|| PhysAddr::new(4503599627370495).align_up(2u64).as_u64()), None, "case 40: physical_align(4503599627370495, 2, true, 0)");
assert_eq!(caught(|| PhysAddr::new(1233).align_down(16u64).as_u64()), Some(1232u64), "case 41: physical_align(1233, 16, false, 0)");
assert_eq!(caught(|| (VirtAddr::new(18446744073709551615) + 1u64).as_u64()), None, "case 42: virtual_add(18446744073709551615, 1)");
assert_eq!(caught(|| (VirtAddr::new(0) - 1u64).as_u64()), None, "case 43: virtual_sub(0, 1)");
assert_eq!(caught(|| (VirtAddr::new(41) + 1u64).as_u64()), Some(42u64), "case 44: virtual_add(41, 1)");
assert_eq!(caught(|| (VirtAddr::new(41) - 1u64).as_u64()), Some(40u64), "case 45: virtual_sub(41, 1)");
assert_eq!(caught(|| (VirtAddr::new(140737488355327) + 1u64).as_u64()), None, "case 46: virtual_add(140737488355327, 1)");
assert_eq!(caught(|| (VirtAddr::new(18446603336221196288) - 1u64).as_u64()), None, "case 47: virtual_sub(18446603336221196288, 1)");
assert_eq!(caught(|| (VirtAddr::new(4503599627370495) + 18446462598732840960u64).as_u64()), None, "case 48: virtual_add(4503599627370495, 18446462598732840960)");
assert_eq!(caught(|| (PhysAddr::new(4503599627370495) + 1u64).as_u64()), None, "case 49: physical_add(4503599627370495, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(0) - 1u64).as_u64()), None, "case 50: physical_sub(0, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(41) + 1u64).as_u64()), Some(42u64), "case 51: physical_add(41, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(41) - 1u64).as_u64()), Some(40u64), "case 52: physical_sub(41, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(140737488355327) + 1u64).as_u64()), Some(140737488355328u64), "case 53: physical_add(140737488355327, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(18446603336221196288) - 1u64).as_u64()), None, "case 54: physical_sub(18446603336221196288, 1, 0)");
assert_eq!(caught(|| (PhysAddr::new(4503599627370495) + 18446462598732840960u64).as_u64()), None, "case 55: physical_add(4503599627370495, 18446462598732840960, 0)");
assert_eq!(Step::forward_checked(VirtAddr::new(0), 0).map(VirtAddr::as_u64), Some(0u64), "case 56: virtual_step(0, 0, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(0), 1).map(VirtAddr::as_u64), Some(1u64), "case 57: virtual_step(0, 1, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355327), 1).map(VirtAddr::as_u64), Some(18446603336221196288u64), "case 58: virtual_step(140737488355327, 1, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(18446603336221196288), 1).map(VirtAddr::as_u64), Some(18446603336221196289u64), "case 59: virtual_step(18446603336221196288, 1, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(18446744073709551615), 1).map(VirtAddr::as_u64), None, "case 60: virtual_step(18446744073709551615, 1, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355327), 20015998343869).map(VirtAddr::as_u64), Some(18446623352219540156u64), "case 61: virtual_step(140737488355327, 20015998343869, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355327), 140737488355328).map(VirtAddr::as_u64), Some(18446744073709551615u64), "case 62: virtual_step(140737488355327, 140737488355328, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355072), 140737488355583).map(VirtAddr::as_u64), Some(18446744073709551615u64), "case 63: virtual_step(140737488355072, 140737488355583, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355072), 140737488355584).map(VirtAddr::as_u64), None, "case 64: virtual_step(140737488355072, 140737488355584, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(140737488355327), 140737488355329).map(VirtAddr::as_u64), None, "case 65: virtual_step(140737488355327, 140737488355329, false)");
assert_eq!(Step::forward_checked(VirtAddr::new(0), 281474976710656).map(VirtAddr::as_u64), None, "case 66: virtual_step(0, 281474976710656, false)");
assert_eq!(Step::backward_checked(VirtAddr::new(0), 0).map(VirtAddr::as_u64), Some(0u64), "case 67: virtual_step(0, 0, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(0), 1).map(VirtAddr::as_u64), None, "case 68: virtual_step(0, 1, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(1), 1).map(VirtAddr::as_u64), Some(0u64), "case 69: virtual_step(1, 1, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446603336221196288), 1).map(VirtAddr::as_u64), Some(140737488355327u64), "case 70: virtual_step(18446603336221196288, 1, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446603336221196289), 1).map(VirtAddr::as_u64), Some(18446603336221196288u64), "case 71: virtual_step(18446603336221196289, 1, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446623352219540156), 20015998343869).map(VirtAddr::as_u64), Some(140737488355327u64), "case 72: virtual_step(18446623352219540156, 20015998343869, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446603336221196288), 140737488355328).map(VirtAddr::as_u64), Some(0u64), "case 73: virtual_step(18446603336221196288, 140737488355328, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446603336221196288), 140737488355073).map(VirtAddr::as_u64), Some(255u64), "case 74: virtual_step(18446603336221196288, 140737488355073, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446603336221196288), 140737488355329).map(VirtAddr::as_u64), None, "case 75: virtual_step(18446603336221196288, 140737488355329, true)");
assert_eq!(Step::backward_checked(VirtAddr::new(18446744073709551615), 281474976710656).map(VirtAddr::as_u64), None, "case 76: virtual_step(18446744073709551615, 281474976710656, true)");
assert_eq!(Step::steps_between(&VirtAddr::new(0), &VirtAddr::new(0)).1.map(|n| n as u64), Some(0u64), "case 77: virtual_steps_between(0, 0)");
assert_eq!(Step::steps_between(&VirtAddr::new(0), &VirtAddr::new(1)).1.map(|n| n as u64), Some(1u64), "case 78: virtual_steps_between(0, 1)");
