assert_eq!(Step::steps_between(&VirtAddr::new(18446603336221196288), &VirtAddr::new(140737488355327)).1.map(|n| n as u64), None, "case 81: virtual_steps_between(18446603336221196288, 140737488355327)");
assert_eq!(Step::steps_between(&VirtAddr::new(18446603336221196288), &VirtAddr::new(18446603336221196288)).1.map(|n| n as u64), Some(0u64), "case 82: virtual_steps_between(18446603336221196288, 18446603336221196288)");
